<?php
/** @var \Lemonade\Profiler\Profile $profile */
$data = $profile->data;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Request detail · Lemonade Profiler</title><link rel="stylesheet" href="<?= $prefix ?>/assets/profiler.css"></head>
<body><header class="top"><a class="brand" href="<?= $prefix ?>"><span class="lemon">L</span> Lemonade <span class="muted">Profiler</span></a><a href="<?= $prefix ?>">← Request history</a></header>
<main><p class="eyebrow">REQUEST PROFILE · <?= gmdate('Y-m-d H:i:s', (int) ($data['created_at'] / 1000000)) ?> UTC</p><h1><span class="method"><?= $this->escape($data['method']) ?></span> <?= $this->escape($data['path'] ?? 'Unmatched request') ?></h1><p class="muted"><?= $this->escape($data['route'] ?? 'No route was published by dispatch') ?></p>
<div class="metrics"><div class="metric"><span>HTTP status</span><strong><?= $this->escape($data['status']) ?></strong></div><div class="metric"><span>Request duration</span><strong><?= $this->ms($data['duration_ms']) ?></strong></div><div class="metric"><span>SQL · <?= $data['sql_count'] ?> queries</span><strong><?= $this->ms($data['sql_ms']) ?></strong></div><div class="metric"><span>PHP peak memory</span><strong><?= $this->memory($data['peak_bytes']) ?></strong></div></div>
<nav class="tabs" aria-label="Profile sections"><a href="#overview">Overview</a><a href="#timeline">Timeline</a><a href="#database">Database</a><a href="#rendering">Rendering</a></nav>
<section class="panel" id="overview"><div class="panel-heading"><h2>Overview</h2><span class="muted">Safe request metadata</span></div><dl><dt>Route</dt><dd><?= $this->escape($data['route']) ?></dd><dt>Route template</dt><dd><?= $this->escape($data['path']) ?></dd><dt>Controller</dt><dd><code><?= $this->escape($data['controller']) ?></code></dd><dt>Action</dt><dd><?= $this->escape($data['action']) ?></dd><dt>Connection setup</dt><dd><?= $data['connection_ms'] === null ? '—' : $this->ms($data['connection_ms']) ?></dd><dt>Profile ID</dt><dd><code><?= $this->escape($data['id']) ?></code></dd></dl></section>
<section class="panel" id="timeline"><div class="panel-heading"><h2>Timeline</h2><span class="muted">Measured intervals</span></div><p class="note">Each row uses the same time origin. Rendering overlaps controller execution; inclusive durations must not be added together. Request duration ends before profiler storage and response emission.</p>
<div class="timeline">
<?php foreach ($this->timeline($profile) as $interval):
$left = min(100.0, 100 * $interval['start'] / max(0.001, $data['duration_ms']));
$width = min(100.0 - $left, 100 * ($interval['duration'] ?? 0) / max(0.001, $data['duration_ms'])); ?>
<div class="span-row"><div><?= $this->escape($interval['label']) ?><small><?= $interval['duration'] === null ? 'Incomplete phase' : $this->ms($interval['duration']) ?> · starts at <?= $this->ms($interval['start']) ?></small></div><div class="track"><span style="margin-left:<?= number_format($left, 4, '.', '') ?>%;width:<?= number_format($width, 4, '.', '') ?>%"></span></div></div>
<?php endforeach; ?></div><details><summary>Raw framework milestones</summary><dl><?php foreach ($data['marks'] as $mark): ?><dt><?= $this->escape($mark['name']) ?></dt><dd><?= $this->ms($mark['elapsed_ms']) ?></dd><?php endforeach; ?></dl></details></section>
<section class="panel" id="database"><div class="panel-heading"><h2>Database</h2><span><?= $data['sql_count'] ?> queries · <?= $this->ms($data['sql_ms']) ?></span></div><p class="note">Execution time includes client preparation and execution. Connection establishment and subsequent row processing are not included. SQL literals and quoted tokens are removed.</p>

<?php if ($data['sql_count'] > count($data['queries'])): ?><p class="note">The detail limit was reached. Totals still include all observed queries.</p><?php endif; ?>
<?php if ($data['queries'] === []): ?><p class="empty">No SQL details captured.</p><?php endif; ?>
<?php foreach ($data['queries'] as $query): ?><article class="query"><div class="query-heading"><span class="muted">#<?= $query['order'] ?></span><span class="<?= $query['slow'] ? 'slow' : '' ?>"><?= $query['slow'] ? 'SLOW · ' : '' ?><?= $this->ms($query['elapsed_ms']) ?></span></div><pre><code><?= $this->escape($query['sql'] ?? 'SQL text unavailable: unsupported syntax or detail length limit.') ?></code></pre></article><?php endforeach; ?></section>
<section class="panel" id="rendering"><div class="panel-heading"><h2>Rendering</h2><span class="muted">Public renderer calls · bounded detail list</span></div><p class="note">Each duration includes layouts and partials performed inside that call. Template data is never captured.</p><div class="table-scroll"><table><thead><tr><th>#</th><th>Template</th><th>Duration</th><th>Result</th></tr></thead><tbody><?php foreach ($data['renderings'] as $rendering): ?><tr><td><?= $rendering['order'] ?></td><td><code><?= $this->escape($rendering['template']) ?></code></td><td><?= $this->ms($rendering['elapsed_ms']) ?></td><td><?= $rendering['completed'] ? 'Completed' : 'Interrupted' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<p class="footnote">Local development only · PHP peak memory is process-wide · Logs and individual middleware durations are not collected.</p></main></body></html>
